<script setup lang="ts">
import { computed, onMounted } from 'vue'; import { storeToRefs } from 'pinia'; import { RouterLink, useRoute } from 'vue-router'; import InventorySubnav from '../components/InventorySubnav.vue'; import { useInventoryStore } from '../runtime/inventory-store'; import './inventory-views.css'
const route=useRoute();const store=useInventoryStore();const{workspace,loading,error}=storeToRefs(store);const warehouseId=computed(()=>String(route.params.warehouseId));const skuId=computed(()=>String(route.params.skuId));const stock=computed(()=>workspace.value.stocks.items.find(x=>x.warehouse.id===warehouseId.value&&x.skuId===skuId.value));const batches=computed(()=>workspace.value.batches.filter(x=>x.warehouse.id===warehouseId.value&&x.batch.skuId===skuId.value));const movements=computed(()=>workspace.value.movements.filter(x=>x.warehouseId===warehouseId.value&&x.skuId===skuId.value));const q=(n:number)=>`${(n/1000).toLocaleString('zh-CN',{maximumFractionDigits:3})}`;onMounted(()=>store.applyQuery({warehouseId:warehouseId.value,keyword:skuId.value,page:1,pageSize:30}))
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><RouterLink to="/inventory/stocks">← 返回库存列表</RouterLink><h1>库存详情</h1><p>仓库、库位、批次与流水共同解释账面数量。</p></div></header><InventorySubnav/><div v-if="error" class="inventory-state error">{{error}}</div><div v-else-if="loading" class="inventory-state">正在加载…</div><div v-else-if="!stock" class="inventory-state"><strong>库存记录不存在</strong></div><template v-else><section class="inventory-panel"><h2>{{stock.sku?.productName??'商品资料不可用'}} · {{stock.sku?.skuCode??stock.skuId}}</h2><p>{{stock.warehouse.name}}（{{stock.warehouse.code}}） · 当前 {{q(stock.currentMilli)}} {{stock.sku?.baseUnitName??'基本单位'}} · 期初 {{q(stock.openingMilli)}}</p><p>待出库、可用、在途：数据源未接入；当前只公开账面库存。</p></section><div class="inventory-toolbar"><strong>库位与批次余额</strong></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>库位</th><th>批次</th><th>生产日期</th><th>有效期</th><th>状态</th><th class="quantity">数量</th></tr></thead><tbody><tr v-for="row in batches" :key="row.batch.id+row.location.id"><td>{{row.location.name}}<small>{{row.location.code}}</small></td><td>{{row.batch.batchNumber}}</td><td>{{row.batch.productionDate??'—'}}</td><td>{{row.batch.expiresOn??'无有效期'}}</td><td><span class="inv-status" :class="`inv-status-${row.status}`">{{row.status}}</span></td><td class="quantity">{{q(row.quantityMilli)}}</td></tr></tbody></table></div><div class="inventory-toolbar"><strong>相关流水（{{movements.length}}）</strong></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>来源</th><th>方向</th><th>批次</th><th class="quantity">变动</th><th class="quantity">变动后</th><th>时间</th></tr></thead><tbody><tr v-for="row in movements" :key="row.id"><td>{{row.sourceType}} · {{row.sourceId}}</td><td>{{row.direction==='inbound'?'入库':'出库'}}</td><td>{{row.batchNumber}}</td><td class="quantity">{{q(row.quantityMilli)}}</td><td class="quantity">{{q(row.balanceAfterMilli)}}</td><td>{{row.occurredAt.slice(0,16).replace('T',' ')}}</td></tr></tbody></table></div></template></section></template>
